/// Determines the winner based on the difference between two values.
/// 
/// # Parameters
/// - `x`: The score of player X.
/// - `y`: The score of player Y.
/// 
/// # Returns
/// - Returns "Alice" if the absolute difference between `x` and `y` is greater than 1,
///   otherwise returns "Brown".
///
/// # Requires
/// - The values of `x` and `y` must be within the range of i8, i.e., -128 <= x, y <= 127.
/// 
/// # Ensures
/// - If the absolute difference between `x` and `y` is greater than 1, the return value is "Alice".
/// - If the absolute difference between `x` and `y` is less than or equal to 1, the return value is "Brown".
#[verus::spec]
fn determine_winner(x: i8, y: i8) -> &'static str {
    // Ensure that the inputs are within the valid range for i8
    assert!((-128..=127).contains(&x));
    assert!((-128..=127).contains(&y));

    // Calculate the absolute difference
    let diff = (x - y).abs();

    // Ensure that the absolute difference is correctly evaluated
    assert!(diff >= 0);
    
    if diff > 1 {
        "Alice"
    } else {
        "Brown"
    }
}